<template><div class="login-page"><el-card class="login-card"><h1>后台管理系统</h1><p>基础框架登录</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" placeholder="用户名" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="密码" /></el-form-item><el-button type="primary" native-type="submit" :loading="loading">登录</el-button></el-form></el-card></div></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{useUserStore}from'@/store/user';const form=reactive({username:'admin',password:'admin123'}),loading=ref(false),router=useRouter(),store=useUserStore();async function submit(){loading.value=true;try{await store.signIn(form.username,form.password);router.push('/')}finally{loading.value=false}}</script>
